var FSNode = function(pterm,pfs,p,k) {
	this.fs = pfs;
	FSNode.term = pterm;
	this.parent = p;
	this.key = k;
	this.sortIndex = Data.UNIQ++;
	this.depth = this.parent == null ? 0 : this.parent.depth + 1;
	this.generateName();
	this.fl_folder = false;
	this.fl_target = false;
	this.fl_deleted = false;
	this.av = null;
	this.content = null;
	this.effects = new haxe_ds_List();
	this.emcList = [];
	if(this.key.indexOf(".antivir") >= 0) {
		this.av = data__$AntivirusXml_AllData.getAntivirus(data_AntivirusXml.get,"avslot");
	}
	if(this.av == null) {
		if(this.key == "file.guardian") {
			this.setLife(AntivirMan.GUARDIAN_LIFE);
		} else if(this.key == "file.core") {
			if(MissionGen.isTutorial(FSNode.term.mdata)) {
				this.setLife(AntivirMan.AV_LIFE);
			} else {
				this.setLife(AntivirMan.CORE_LIFE);
			}
		} else if(this.key == "file.control") {
			this.setLife(AntivirMan.AV_LIFE);
		} else {
			this.setLife(1);
		}
	} else if(this.av.key == "bomb") {
		this.setLife(1);
	} else {
		this.setLife(AntivirMan.AV_LIFE);
	}
	this.freezeTimer = 0;
};
