FSNode.attach = function(dm,fl_anim,fnode,index) {
	if(index == null) {
		index = 0;
	}
	var mc = dm.attach("file",Data.DP_ITEM);
	mc.gotoAndStop(mc._totalframes);
	var x = index % FSNode.ICON_BY_LINE;
	var y = Math.floor(index / FSNode.ICON_BY_LINE);
	var hexWid = 170;
	var hexHei = 85;
	var _this = mc;
	_this.x = 5 + x * hexWid * 0.5 + y * hexWid * 0.5;
	var _this = mc;
	_this.y = 200 + -x * hexHei * 0.5 + y * hexHei * 0.5;
	var name = fnode != null ? fnode.getName() : null;
	MCField.get_field(mc).text = name;
	MCField.get_field(mc).x += (120 - MCField.get_field(mc).width) / 2;
	MCField.get_field(mc).y += 5;
	var _this = MCField.get_field(MCFile.get_bar(mc));
	_this.visible = false;
	var _this = MCFile.get_bar(mc);
	_this.visible = false;
	if(fnode != null) {
		fnode.mcIndex = index;
		fnode.mc = mc;
		fnode.redraw();
	} else {
		MCField.get_field(mc).visible = false;
	}
	if(fl_anim) {
		var delay = -0.08 * index - Std.random(35) / 100;
		var a = FSNode.term.startAnim(AnimType.A_FadeIn,mc,name,delay);
		a.spd *= 1.8;
		var at = FSNode.term.startAnim(AnimType.A_Text,mc,name,delay);
		at.spd *= 1.8;
		var ap = FSNode.term.startAnim(AnimType.A_PlayFrames,mc,name,delay);
		ap.spd *= 1.8;
		var _g = 0;
		var _g1 = fnode.emcList;
		while(_g < _g1.length) {
			var emc = _g1[_g];
			++_g;
			var ae = FSNode.term.startAnim(AnimType.A_FadeIn,emc,null,delay);
			ae.spd *= 1.8;
		}
	} else {
		var a = FSNode.term.startAnim(AnimType.A_FadeIn,mc,null,-index * 0.06);
		a.spd *= 1.2;
	}
	return mc;
};
