			if(FSNode.term.hasChipset(data__$ChipsetsXml_AllData.getChipsetData(data_ChipsetsXml.get,"unmask"))) {
				var _g = 0;
				var _g1 = this.name.length;
				while(_g < _g1) {
					var i = _g++;
					if((this.id + i) % 3 == 0) {
						str += this.name.charAt(i);
					} else {
						str += "*";
					}
				}
			} else {
				var _g = 0;
				var _g1 = this.name.length;
				while(_g < _g1) {
					var i = _g++;
					str += "*";
				}
			}
			return str;
