	,divideInBills: function(total,piles,bills) {
		if(piles <= 0) {
			return [];
		}
		if(bills.length == 0) {
			return [];
		}
		bills.sort(Reflect.compare);
		total = Math.floor(total / bills[0]) * bills[0];
		var list = [];
		var i = bills.length - 1;
		while(i >= 0 && total > 0) if(bills[i] <= total) {
			total -= bills[i];
			list.push(bills[i]);
		} else {
			--i;
		}
		list.sort(Reflect.compare);
		if(piles > list.length) {
			var highest = list[list.length - 1];
			var newBills = Lambda.array(Lambda.filter(bills,function(n) {
				return n < highest;
			}));
			if(newBills.length > 0) {
				var broken = this.divideInBills(highest,piles - list.length + 1,newBills);
				if(broken.length > 0) {
					list.pop();
					list = broken.concat(list);
					list.sort(Reflect.compare);
				}
			}
		}
		return list;
	}
