	,addFx: function(dm,depth,type,link,x,y) {
		if(link == null) {
			link = "fx";
		}
		if(depth == null) {
			depth = Data.DP_FX;
		}
		if(dm == null) {
			dm = Manager.DM;
		}
		var mc = dm.attach(link,depth);
		mc.gotoAndStop(Std.random(mc._totalframes) + 1);
		var _this = mc;
		_this.x = x;
		var _this = mc;
		_this.y = y;
		var fx = { type : type, mc : mc, dx : 0.0, dy : 0.0, gx : 0.0, gy : 0.0, timer : 0.0, data : 0.0};
		switch(fx.type._hx_index) {
		case 0:
			fx.dy = -1;
			break;
		case 1:
			var _this = mc;
			_this.x = mc.x + Std.random(28) * (Std.random(2) * 2 - 1);
			var _this = mc;
			_this.y = mc.y + Std.random(10);
			mc.set__alpha(Std.random(70) + 30);
			fx.dy = -Std.random(20) / 10 - 0.3;
			fx.data = Std.random(314) / 100;
			break;
		case 2:
			var fxFrame = Std.random(fx.mc._totalframes) + 1;
			mc.gotoAndStop(fxFrame);
			if(mc.get_smc() != null) {
				mc.get_smc().gotoAndStop(1);
			}
			if(link == "fx_glight") {
				var s = Std.random(70) + 30;
				mc.set__xscale((Std.random(2) * 2 - 1) * s);
				mc.set__yscale((Std.random(2) * 2 - 1) * s);
				mc.set__alpha(Std.random(60) + 40);
				mc.filters = common_GlowFilter.create(16777215,0.7,8,8,3);
			}
			break;
		case 3:
			fx.dx = Std.random(30) + 30;
			fx.dy = fx.dx * 0.5;
			mc.set__xscale(50 + Std.random(30));
			mc.set__yscale(mc.get__xscale());
			switch(Std.random(2)) {
			case 0:
				var _this = mc;
				_this.x = -650 + Std.random(50);
				var _this = mc;
				_this.y = 800;
				fx.dy *= -1;
				break;
			case 1:
				var _this = mc;
				_this.x = 550 + Std.random(50);
				var _this = mc;
				_this.y = 200;
				fx.dx *= -1;
				break;
			}
			if(fx.dx > 0 && fx.dy > 0) {
				mc.set__xscale(mc.get__xscale() * -1);
				mc.set__yscale(mc.get__yscale() * -1);
			}
			if(fx.dx > 0 && fx.dy < 0) {
				mc.set__xscale(mc.get__xscale() * -1);
			}
			if(fx.dx < 0 && fx.dy > 0) {
				mc.set__yscale(mc.get__yscale() * -1);
			}
			mc.set__alpha(Std.random(35) + 15);
			break;
		}
		this.fxList.push(fx);
		return fx;
	}
