	,autoComplete: function(parent,str) {
		this.hideCompletion();
		var original = str;
		str = Data.trimSpaces(str);
		while(str.indexOf("  ") >= 0) str = StringTools.replace(str,"  "," ");
		var end = str.indexOf(" ");
		if(end < 0) {
			end = 999;
		}
		var virusId = HxOverrides.substr(str,0,end).toLowerCase();
		var target = HxOverrides.substr(str,end + 1,null).toLowerCase();
		var clist = new haxe_ds_List();
		if(target == null || target.length == 0) {
			var _g_head = this.dock.getCurrentViruses().h;
			while(_g_head != null) {
				var val = _g_head.item;
				_g_head = _g_head.next;
				var v = val;
				if(v.id.toLowerCase().indexOf(virusId) == 0 && v.target != "_net" && (v.uses == null || v.uses > 0)) {
					clist.add(v.id);
				}
			}
			var _g_head = data_VirusXml.getCategory("hidden",this.gameLevel,true).h;
			while(_g_head != null) {
				var val = _g_head.item;
				_g_head = _g_head.next;
				var v = val;
				if(v.id.toLowerCase().indexOf(virusId) == 0 && v.target != "_net") {
					clist.add(v.id);
				}
			}
		} else {
			var _g = 0;
			var _g1 = this.fs.getFolderFiles(parent);
			while(_g < _g1.length) {
				var f = _g1[_g];
				++_g;
				if(!f.fl_deleted && !f.hasEffect(EffectType.E_Masked) && f.name.toLowerCase().indexOf(target) == 0) {
					clist.add(f.name);
				}
			}
		}
		var h = this.aliases.h;
		var from_h = h;
		var from_keys = Object.keys(h);
		var from_length = from_keys.length;
		var from_current = 0;
		while(from_current < from_length) {
			var from = from_keys[from_current++];
			clist.add(from);
		}
		var _g_head = clist.h;
		while(_g_head != null) {
			var val = _g_head.item;
			_g_head = _g_head.next;
			var a = val;
			var n = 0;
			var _g_head1 = clist.h;
			while(_g_head1 != null) {
				var val1 = _g_head1.item;
				_g_head1 = _g_head1.next;
				var b = val1;
				if(a == b) {
					++n;
				}
			}
			while(n > 1) {
				clist.remove(a);
				--n;
			}
		}
		if(clist.length == 0) {
			return original;
		} else if(target.length > 0) {
			var comp = this.getCompletion(target,clist);
			if(comp.isBest) {
				return virusId + " " + comp.result + " ";
			} else {
				this.showCompletion(comp.all);
				return virusId + " " + comp.result;
			}
		} else {
			var comp = this.getCompletion(virusId,clist);
			if(comp.isBest) {
				return comp.result + " ";
			} else {
				this.showCompletion(comp.all);
				return comp.result;
			}
		}
	}
	,getCompletion: function(str,list) {
		var matches = new haxe_ds_List();
		var _g_head = list.h;
		while(_g_head != null) {
			var val = _g_head.item;
			_g_head = _g_head.next;
			var w = val;
			if(w.toLowerCase().indexOf(str.toLowerCase()) == 0) {
				matches.add(w);
			}
		}
		if(matches.length == 0) {
			return { isBest : false, all : matches, result : str};
		}
		if(matches.length == 1) {
			return { isBest : true, all : matches, result : matches.first()};
		}
		var common = "";
		var i = 0;
		while(i < matches.first().length) {
			var c = matches.first().charAt(i).toLowerCase();
			if(c == null || c.length == 0) {
				break;
			}
			var fl_match = true;
			var _g_head = matches.h;
			while(_g_head != null) {
				var val = _g_head.item;
				_g_head = _g_head.next;
				var m = val;
				if(m.toLowerCase().charAt(i) != c) {
					fl_match = false;
				}
			}
			if(!fl_match) {
				break;
			}
			common += c;
			++i;
		}
		return { isBest : false, all : matches, result : common};
	}
	,showSystemGame: function(file) {
		this.detachSystemGame();
		this.dock.lock();
		this.dock.hide();
		var _g = this;
		var fl_unlock = true;
		this.attachMask(function() {
			_g.detachSystemGame(fl_unlock);
		});
		var list = [];
		var _g1 = 0;
		while(_g1 < 3) {
			var y = _g1++;
			var _g2 = 0;
			while(_g2 < 3) {
				var x = _g2++;
				var mc = Manager.DM.attach("sysGameCube",Data.DP_TOP);
				var w = mc.width + 1;
				var _this = mc;
				_this.x = 100 + x * w;
				var _this1 = mc;
				_this1.y = 50 + y * w;
				mc.get_smc().stop();
				if(file.allowMatrix[x][y]) {
					mc.set_onRelease((function(_g,y,x,mc,file) {
						return function() {
							_g[0].onActivateMatrix(file[0],mc[0],x[0],y[0]);
						};
					})([this],[y],[x],[mc],[file]));
					mc.get_smc().filters = common_GlowFilter.create(10875441,1,10,10,3,1,true);
				}
				var tmp = this.fs.matrix[x][y] ? 2 : 1;
				mc.get_smc().gotoAndStop(tmp);
				this.sysGameList.push(mc);
				if(Std.random(2) == 0) {
					this.startAnim(AnimType.A_BubbleIn,mc,null,-Std.random(120) / 100);
				} else {
					this.startAnim(AnimType.A_FadeIn,mc,null,-Std.random(120) / 100).spd *= 1.5;
				}
			}
		}
		Data.zsort(Manager.DM,this.sysGameList);
	}
	,onActivateMatrix: function(file,mc,x,y) {
		if(this.fs.fl_auth) {
			return;
		}
		if(this.fs.matrix[x][y]) {
			this.fs.matrix[x][y] = false;
		} else {
			var max = 2;
			var n = 0;
			if(this.fs.matrix[0][0] && file.allowMatrix[0][0]) {
				++n;
			}
			if(this.fs.matrix[0][1] && file.allowMatrix[0][1]) {
				++n;
			}
			if(this.fs.matrix[0][2] && file.allowMatrix[0][2]) {
				++n;
			}
			if(this.fs.matrix[1][0] && file.allowMatrix[1][0]) {
				++n;
			}
			if(this.fs.matrix[1][1] && file.allowMatrix[1][1]) {
				++n;
			}
			if(this.fs.matrix[1][2] && file.allowMatrix[1][2]) {
				++n;
			}
			if(this.fs.matrix[2][0] && file.allowMatrix[2][0]) {
				++n;
			}
			if(this.fs.matrix[2][1] && file.allowMatrix[2][1]) {
				++n;
			}
			if(this.fs.matrix[2][2] && file.allowMatrix[2][2]) {
				++n;
			}
			if(n >= max) {
				this.popUp("can't tag more than " + max + " slots");
				return;
			}
			this.fs.matrix[x][y] = true;
		}
		if(Data.hasLine(this.fs.matrix)) {
			this.fs.corrupt();
			this.detachSystemGame(true);
		}
		var tmp = this.fs.matrix[x][y] ? 2 : 1;
		mc.get_smc().gotoAndStop(tmp);
	}
	,detachSystemGame: function(fl_unlock) {
		if(fl_unlock == null) {
			fl_unlock = false;
		}
		this.detachMask();
		var _g = 0;
		var _g1 = this.sysGameList;
		while(_g < _g1.length) {
			var mc = _g1[_g];
			++_g;
			this.startAnim(AnimType.A_FadeRemove,mc,null,-Std.random(50) / 100).spd *= 2;
		}
		this.sysGameList = [];
		if(fl_unlock) {
			this.dock.unlock();
			this.fs.clearTarget();
		}
		this.dock.show();
	}
