	,check: function() {
		var list = Type.getInstanceFields(VirusMan);
		var err = [];
		var h = data_VirusXml.ALL.h;
		var e_h = h;
		var e_keys = Object.keys(h);
		var e_length = e_keys.length;
		var e_current = 0;
		while(e_current < e_length) {
			var e = e_h[e_keys[e_current++]];
			if(e.id.length > 6) {
				err.push("ID is too long : " + e.id);
			}
			if(!HxOverrides.remove(list,"_" + e.id)) {
				err.push("Virus not implemented : " + e.id);
			}
		}
		var _g = 0;
		while(_g < list.length) {
			var m = list[_g];
			++_g;
			if(m.charAt(0) == "_") {
				err.push("Unknown virus implementation : " + m);
			}
		}
		if(err.length > 0) {
			throw haxe_Exception.thrown(err.join("\n") + "\n");
		}
	}
	,getCT: function(f) {
		var ct = 1.0 / this.term.getSpeed();
		if(f != null) {
			ct *= f.size;
		}
		return ct;
	}
	,start: function(ct,cb) {
		var me = this;
		if(ct == null) {
			ct = this.getCT();
		}
		if(this.term.fl_leet && this.virus.target != "_net") {
			ct = 0.1;
		}
		switch(this.virus.target) {
		case "_folder":
			me.term.playSound("bleep_04");
			break;
		case "_net":
			me.term.playSound("bleep_05");
			me.term.playSound("modem_03",Std.random(200) / 100);
			break;
		default:
			me.term.playSound("bleep_01");
		}
		Progress.start(ct,function() {
			if(me.virus.uses != null) {
				var fh = me.virus;
				fh.uses--;
				if(me.virus.uses == 0) {
					me.term.dock.onDepleted(me.virus);
				}
			}
			cb(me.term,me.virus);
			me.term.checkMission();
			me.term.spam(me.virus.id + " OK");
			me.term.avman.onVirusRun(me.virus);
			me.term.decayLog();
			me.term.hideCompletion();
			me.term.dock.updateBubbles();
			if(me.term.hasEffect(UserEffectType.UE_Furtivity)) {
				me.term.avman.endTurn.add(function() {
					me.term.removeEffect(UserEffectType.UE_Furtivity);
					me.term.log((_$Lang_AllTextsFormat.getText(Lang.fmt,"RemainingFurtivity"))({ _n : me.term.countEffect(UserEffectType.UE_Furtivity)}));
				});
			}
			if(me.virus.cat == "damage" && me.term.hasChipset(data__$ChipsetsXml_AllData.getChipsetData(data_ChipsetsXml.get,"brute"))) {
				me.term.loseMana(Math.round(me.virus.cc * VirusMan.BRUTE_CC));
			} else {
				me.term.loseMana(me.virus.cc);
			}
		},this.virus.name,ct >= 3 ? BarAnim.BA_Slow : BarAnim.BA_Normal);
		this.term.detachBubble();
	}
	,canBeDamaged: function(f) {
		if(this.term.hasChipset(data__$ChipsetsXml_AllData.getChipsetData(data_ChipsetsXml.get,"scout"))) {
			if(f.key == "file.core" || f.key == "file.guardian") {
				throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"NotInScoutMode"));
			}
		}
		if(!f.fl_deleted && f.life > 0) {
			return !f.fl_folder;
		} else {
			return false;
		}
	}
