	,_connec: function(n) {
		if(n.type == NodeType.Entrance) {
			this.term.logout();
			return;
		}
		if(this.term.isDisabled()) {
			throw haxe_Exception.thrown(this.term.getDisableReason());
		}
		if(!n.system.canConnect()) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"InvalidTarget"));
		}
		if(this.term.net.isShielded(n)) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"SystemLocked"));
		}
		var mc = Manager.DM.attach("pop",Data.DP_FX);
		Manager.loading((_$Lang_AllTextsFormat.getText(Lang.fmt,"ConnectingPopUp"))({ _ip : n.ip}));
		if(n.system.fl_crashed) {
			this.term.startAnim(AnimType.A_Connect,mc,n.ip,null,true).data = -1;
		} else {
			this.term.startAnim(AnimType.A_Connect,mc,n.ip,null,true);
		}
		this.term.log(_$Lang_AllTexts.getText(Lang.get,"Log_Connecting"));
		if(this.term.fs != null) {
			this.term.fs.lock();
		}
		this.start(this.getCT() * 2,function(t,v) {
			t.net.connect(n);
			if(t.fs != null) {
				t.fs.logEvent((_$Lang_AllTextsFormat.getText(Lang.fmt,"TraceConnect"))({ _name : t.username}));
			}
			Tutorial.play(_$Tutorial_AllData.getTutorial(Tutorial.get,"third"),"openSys");
			Tutorial.play(_$Tutorial_AllData.getTutorial(Tutorial.get,"third"),"copyFile2");
		});
	}
