	,_copy: function(f) {
		if(this.term.avman.systemContains(data__$AntivirusXml_AllData.getAntivirus(data_AntivirusXml.get,"couveuse"))) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"Couveuse"));
		}
		if(f.fl_folder || f.av != null) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"InvalidTarget"));
		}
		if(!this.canBeDamaged(f)) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"InvalidTarget"));
		}
		if(f.hasEffect(EffectType.E_Masked) || f.hasEffect(EffectType.E_Encoded)) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"CantCopyCrypted"));
		}
		if(f.key == "file.pack") {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"CantCopyPack"));
		}
		if(f.key == "file.log") {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"CantCopyLog"));
		}
		if(f.hasEffect(EffectType.E_Copy)) {
			throw haxe_Exception.thrown(_$Lang_AllTexts.getText(Lang.get,"Useless"));
		}
		if(this.term.storage.length >= this.term.getMaxStorage()) {
			throw haxe_Exception.thrown((_$Lang_AllTextsFormat.getText(Lang.fmt,"DiskFull"))({ _max : this.term.getMaxStorage()}));
		}
		this.start(this.getCT(f),function(t,v) {
			t.copyFile(f);
			f.addEffect(EffectType.E_Copy);
			t.log((_$Lang_AllTextsFormat.getText(Lang.fmt,"Log_Copied"))({ _name : f.name, _n : t.storage.length, _max : t.getMaxStorage()}));
			if(f.fl_target) {
				Tutorial.play(_$Tutorial_AllData.getTutorial(Tutorial.get,"third"),"copied");
			}
		});
	}
