	,_corrup: function(f) {
		this.checkCorrupt(f);
		this.start(this.getCT(f) * 0.25,function(t,v) {
			f.addEffect(EffectType.E_Corrupt);
			var lines = f.content.split("\n");
			var str = "";
			var _g = 0;
			while(_g < lines.length) {
				var l = lines[_g];
				++_g;
				if(l.indexOf("//") >= 0) {
					str += l + "\n";
				} else {
					str += "<del>" + l + "</del>\n";
				}
			}
			f.changeContent(str + "\n" + TD.texts.get("cfLineHacker"));
			t.addIconRain(t.fs.sdm,["fx_corrupt"],null,f.mc);
			t.fs.onCorruptControl();
		});
	}
